package thaumcraft.thaumaturgy;
import java.util.*;
import com.mojang.serialization.JsonOps;
import com.google.gson.JsonParser;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class FocusGraphTest {
    FocusProgram node(String medium,String kind){return new FocusProgram(medium,List.of(new FocusProgram.Effect(kind,1,1)));}
    @Test void nestedGraphsRoundTripWithGlobalCostsAndExactCrystals(){var graph=node("projectile","air").withChild(0,node("bolt","fire").modifier("split_target").withChild(1,node("touch","heal")));assertTrue(graph.valid());assertEquals(4,graph.totalEffects());assertEquals(Map.of("motus",1,"aer",1,"potentia",1,"ignis",2,"aversio",1,"victus",1),graph.crystals());assertEquals(29,graph.complexity());assertEquals(graph,FocusProgram.CODEC.parse(JsonOps.INSTANCE,FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,graph).getOrThrow()).getOrThrow());assertEquals(3,graph.graphNodes().size());}
    @Test void depthIsBoundedAtFourAndCodecRejectsFifthLevel(){var graph=node("touch","air");for(int i=0;i<3;i++)graph=node("touch","air").withChild(0,graph);assertTrue(graph.valid());assertEquals(graph,FocusProgram.CODEC.parse(JsonOps.INSTANCE,FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,graph).getOrThrow()).getOrThrow());var invalid=node("touch","air").withChild(0,graph);assertFalse(invalid.valid());assertTrue(FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,invalid).error().isPresent());var json=FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,graph).getOrThrow().getAsJsonObject();var at=json;for(int i=0;i<3;i++)at=at.getAsJsonArray("next").get(0).getAsJsonObject();at.add("next",JsonParser.parseString("[{\"medium\":\"touch\",\"effects\":[{\"kind\":\"air\",\"power\":1,\"duration\":1}]}]"));assertTrue(FocusProgram.CODEC.parse(JsonOps.INSTANCE,json).error().isPresent());}
    @Test void scatterProductsAreBoundedBeforeExecution(){var child=new FocusProgram("bolt",node("bolt","air").effects(),"scatter",10,10,1,5,false,List.of());var graph=new FocusProgram("projectile",child.effects(),"scatter",10,10,1,5,false,List.of()).withChild(0,child);assertEquals(110,graph.executionBound());assertFalse(graph.valid());assertTrue(FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,graph).error().isPresent());assertTrue(node("projectile","air").modifier("scatter").withChild(0,child).valid());}
    @Test void addressEditsAndModifierChangesKeepSiblingSettings(){var graph=node("projectile","earth").modifier("split_trajectory").withChild(0,node("touch","fire")).withChild(1,node("bolt","frost"));var changed=graph.replaceAt(List.of(0),graph.at(List.of(0)).modifier("scatter"));assertEquals(graph.child(1),changed.child(1));assertEquals("scatter",changed.child(0).modifier());assertEquals(changed.next(),changed.modifier("none").next());assertEquals(graph.child(1),graph.path(1).child(0));assertNull(graph.at(List.of(0,0)));assertNull(graph.at(List.of(2)));}
    @Test void planExclusionAndGlobalEffectBoundsRemainEnforced(){assertFalse(node("plan","break").withChild(0,node("touch","fire")).valid());assertFalse(node("touch","fire").withChild(0,node("plan","break")).valid());var eight=new FocusProgram("touch",Collections.nCopies(7,new FocusProgram.Effect("fire",1,1))).withChild(0,node("bolt","air"));assertTrue(eight.valid());assertFalse(eight.withChild(0,node("bolt","air").withChild(0,node("touch","heal"))).valid());}
    @Test void repeatedMediaAcrossLevelsPayGlobalSurcharge(){var graph=node("touch","air").withChild(0,node("touch","air"));assertEquals(10,graph.complexity());assertEquals(Map.of("aversio",2,"aer",2),graph.crystals());}
}
